// validateQuerySafety checks if a query is safe to execute
// It blocks mutations and DDL operations while allowing SELECT and EXPLAIN
func validateQuerySafety(query string) error {
	// Normalize the query: trim whitespace and convert to uppercase for checking
	normalized := strings.TrimSpace(query)
	if normalized == "" {
		return usageErr("query cannot be empty")
	}

	upperQuery := strings.ToUpper(normalized)

	// Blocklist: keywords that indicate unsafe operations
	blockedKeywords := []string{
		"INSERT",
		"UPDATE",
		"DELETE",
		"CREATE",
		"ALTER",
		"DROP",
		"TRUNCATE",
		"BEGIN",
		"COMMIT",
		"ROLLBACK",
		"GRANT",
		"REVOKE",
	}

	// Check for blocked keywords appearing as SQL keywords (with word boundaries)
	for _, keyword := range blockedKeywords {
		if containsKeyword(upperQuery, keyword) {
			return apiErr("mutations not allowed via query command; use psql for full SQL access")
		}
	}

	// Extract the first word of the query (the main statement keyword)
	firstWord := extractFirstKeyword(upperQuery)

	// Allowlist: queries that are safe to execute
	allowedKeywords := map[string]bool{
		"SELECT":       true,
		"EXPLAIN":      true,
		"WITH":         true, // CTE is allowed as long as it ends with SELECT
		"SHOW":         true,
		"DESCRIBE":     true, // PostgreSQL shorthand for DESC
		"DESC":         true,
	}

	// For WITH (CTE), validate that it contains a SELECT
	if firstWord == "WITH" {
		// Check that SELECT appears in the query
		if !strings.Contains(upperQuery, "SELECT") {
			return apiErr("WITH clause must be followed by a SELECT statement")
		}
	}

	// Allow EXPLAIN, SHOW, and other introspection queries
	if firstWord == "EXPLAIN" || firstWord == "SHOW" || firstWord == "DESCRIBE" || firstWord == "DESC" {
		return nil
	}

	// Check if it's in the allowlist
	if !allowedKeywords[firstWord] {
		return apiErr("query type not allowed; only SELECT, EXPLAIN, SHOW, and introspection queries are permitted")
	}

	return nil
}

// containsKeyword checks if a keyword appears in the query as a complete word
func containsKeyword(query, keyword string) bool {
	// Find all occurrences of the keyword
	for {
		idx := strings.Index(query, keyword)
		if idx == -1 {
			return false
		}

		// Check that it's a complete word (preceded and followed by non-alphanumeric chars)
		// Before the keyword
		if idx > 0 {
			prevChar := query[idx-1]
			if isWordChar(rune(prevChar)) {
				// Not a word boundary, skip this occurrence
				query = query[idx+1:]
				continue
			}
		}

		// After the keyword
		afterIdx := idx + len(keyword)
		if afterIdx < len(query) {
			nextChar := query[afterIdx]
			if isWordChar(rune(nextChar)) {
				// Not a word boundary, skip this occurrence
				query = query[idx+1:]
				continue
			}
		}

		// It's a complete word
		return true
	}
}

// isWordChar checks if a character is alphanumeric or underscore
func isWordChar(ch rune) bool {
	return (ch >= 'A' && ch <= 'Z') || (ch >= 'a' && ch <= 'z') || (ch >= '0' && ch <= '9') || ch == '_'
}

// extractFirstKeyword extracts the first SQL keyword from a query
func extractFirstKeyword(query string) string {
	// Remove leading whitespace and comments
	cleaned := strings.TrimSpace(query)

	// Remove leading SQL comments (-- and /* ... */)
	for {
		if strings.HasPrefix(cleaned, "--") {
			// Skip single-line comment
			if idx := strings.Index(cleaned, "\n"); idx >= 0 {
				cleaned = strings.TrimSpace(cleaned[idx:])
			} else {
				return ""
			}
		} else if strings.HasPrefix(cleaned, "/*") {
			// Skip multi-line comment
			if idx := strings.Index(cleaned, "*/"); idx >= 0 {
				cleaned = strings.TrimSpace(cleaned[idx+2:])
			} else {
				return ""
			}
		} else {
			break
		}
	}

	// Split on whitespace and get the first word
	parts := strings.Fields(cleaned)
	if len(parts) == 0 {
		return ""
	}

	return strings.ToUpper(parts[0])
}

// parseParams splits the parameter string by pipe delimiter
func parseParams(paramsStr string) ([]interface{}, error) {
	if paramsStr == "" {
		return nil, nil
	}

	params := strings.Split(paramsStr, "|")
	result := make([]interface{}, len(params))
	for i, param := range params {
		result[i] = strings.TrimSpace(param)
	}
	return result, nil
}

// convertRowsToMaps converts pgx.Rows to a slice of maps
func convertRowsToMaps(rows pgx.Rows) ([]map[string]interface{}, error) {
	var results []map[string]interface{}

	// Get the field descriptions (column names and types)
	fieldDescs := rows.FieldDescriptions()

	// Iterate through rows
	for rows.Next() {
		values, err := rows.Values()
		if err != nil {
			return nil, fmt.Errorf("reading row values: %w", err)
		}

		// Convert values to map with column names as keys
		row := make(map[string]interface{})
		for i, fieldDesc := range fieldDescs {
			if i < len(values) {
				row[string(fieldDesc.Name)] = values[i]
			}
		}

		results = append(results, row)
	}

	// Check for iteration errors
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterating rows: %w", err)
	}

	return results, nil
}
